   357→// ValidateCheckpointDeep performs comprehensive validation of checkpoint metadata
   358→// on the checkpoint branch, including transcript JSONL validity, content hash
   359→// verification, and prompt content checking.
   360→func ValidateCheckpointDeep(t *testing.T, dir string, v DeepCheckpointValidation) {
   361→	t.Helper()
   362→
   363→	// Basic metadata validation
   364→	AssertCheckpointExists(t, dir, v.CheckpointID)
   365→	AssertCheckpointMetadataComplete(t, dir, v.CheckpointID)
   366→
   367→	if v.Strategy != "" {
   368→		meta := ReadCheckpointMetadata(t, dir, v.CheckpointID)
   369→		assert.Equal(t, v.Strategy, meta.Strategy,
   370→			"checkpoint %s: strategy mismatch", v.CheckpointID)
   371→	}
   372→
   373→	if len(v.FilesTouched) > 0 {
   374→		AssertCheckpointFilesTouched(t, dir, v.CheckpointID, v.FilesTouched)
   375→	}
   376→
   377→	path := CheckpointPath(v.CheckpointID)
   378→
   379→	// Validate session metadata exists and has checkpoint_id
   380→	sessionBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/metadata.json", path)
   381→	sessionRaw := gitOutputSafe(dir, "show", sessionBlob)
   382→	if assert.NotEmpty(t, sessionRaw, "session metadata should exist at %s", sessionBlob) {
   383→		var sessionMeta map[string]any
   384→		if assert.NoError(t, json.Unmarshal([]byte(sessionRaw), &sessionMeta)) {
   385→			assert.Equal(t, v.CheckpointID, sessionMeta["checkpoint_id"],
   386→				"session metadata checkpoint_id should match")
   387→			assert.NotEmpty(t, sessionMeta["created_at"], "session metadata should have created_at")
   388→		}
   389→	}
   390→
   391→	// Validate transcript is valid JSONL
   392→	transcriptBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/full.jsonl", path)
   393→	transcriptRaw := gitOutputSafe(dir, "show", transcriptBlob)
   394→	if assert.NotEmpty(t, transcriptRaw, "transcript should exist at %s", transcriptBlob) {
   395→		lines := strings.Split(transcriptRaw, "\n")
   396→		nonEmpty := 0
   397→		for _, line := range lines {
   398→			if strings.TrimSpace(line) != "" {
   399→				nonEmpty++
   400→			}
   401→		}
   402→		assert.Positive(t, nonEmpty, "transcript should have at least one line")
   403→
   404→		for _, expected := range v.ExpectedTranscriptContent {
   405→			assert.Contains(t, transcriptRaw, expected,
   406→				"transcript should contain %q", expected)
   407→		}
   408→
   409→		// Validate content hash
   410→		hashBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/content_hash.txt", path)
   411→		hashRaw := gitOutputSafe(dir, "show", hashBlob)
   412→		if hashRaw != "" {
   413→			hash := sha256.Sum256([]byte(transcriptRaw))
   414→			expectedHash := "sha256:" + hex.EncodeToString(hash[:])
   415→			assert.Equal(t, expectedHash, strings.TrimSpace(hashRaw),
   416→				"content hash should match transcript SHA-256")
   417→		}
   418→	}
   419→
   420→	// Validate prompt.txt if expected prompts specified
   421→	if len(v.ExpectedPrompts) > 0 {
   422→		promptBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/prompt.txt", path)
   423→		promptRaw := gitOutputSafe(dir, "show", promptBlob)
   424→		for _, expected := range v.ExpectedPrompts {
   425→			assert.Contains(t, promptRaw, expected,
   426→				"prompt.txt should contain %q", expected)
   427→		}
   428→	}
   429→}
