   150→func configureDroidRepoSettings(repoDir string) error {
   151→	home, err := os.UserHomeDir()
   152→	if err != nil {
   153→		return fmt.Errorf("get home dir: %w", err)
   154→	}
   155→
   156→	globalSettingsPath := filepath.Join(home, ".factory", "settings.json")
   157→	repoSettingsPath := filepath.Join(repoDir, droidRepoSettingsPath)
   158→
   159→	if err := mergeDroidCustomModels(globalSettingsPath, repoSettingsPath); err != nil {
   160→		return err
   161→	}
   162→	if err := ensureGitInfoExcludeContains(repoDir, droidRepoSettingsPath); err != nil {
   163→		return fmt.Errorf("exclude droid settings from git: %w", err)
   164→	}
   165→	return nil
   166→}
   167→
   168→func mergeDroidCustomModels(globalSettingsPath, repoSettingsPath string) error {
   169→	globalSettings, err := loadJSONMap(globalSettingsPath, "global droid settings")
   170→	if err != nil {
   171→		return err
   172→	}
   173→
   174→	customModels, ok := globalSettings["customModels"]
   175→	if !ok {
   176→		return fmt.Errorf(
   177→			"global droid settings at %s missing customModels; repo-local %s shadows global settings",
   178→			globalSettingsPath,
   179→			repoSettingsPath,
   180→		)
   181→	}
   182→
   183→	var models []json.RawMessage
   184→	if err := json.Unmarshal(customModels, &models); err != nil {
   185→		return fmt.Errorf("parse customModels in %s: %w", globalSettingsPath, err)
   186→	}
   187→	if len(models) == 0 {
   188→		return fmt.Errorf("global droid settings at %s has empty customModels", globalSettingsPath)
   189→	}
   190→
   191→	repoSettings, err := loadJSONMap(repoSettingsPath, "repo-local droid settings")
   192→	if err != nil {
   193→		return err
   194→	}
   195→	repoSettings["customModels"] = customModels
   196→
   197→	// Set the active custom model so interactive mode uses the BYOK model
   198→	// instead of prompting for selection. The value must match the Model
   199→	// field from the customModels entry (not the displayName).
   200→	modelJSON, err := json.Marshal(agents.DefaultDroidModel())
   201→	if err != nil {
   202→		return fmt.Errorf("marshal model setting: %w", err)
   203→	}
   204→	repoSettings["model"] = json.RawMessage(modelJSON)
   205→
   206→	// High autonomy prevents Droid from asking for confirmation during
   207→	// interactive E2E tests, which would cause hangs waiting for input.
   208→	repoSettings["autonomyMode"] = json.RawMessage(`"auto-high"`)
   209→	repoSettings["completionSound"] = json.RawMessage(`"off"`)
   210→
   211→	out, err := json.MarshalIndent(repoSettings, "", "  ")
   212→	if err != nil {
   213→		return fmt.Errorf("marshal repo-local droid settings: %w", err)
   214→	}
   215→	out = append(out, '\n')
   216→
   217→	if err := os.WriteFile(repoSettingsPath, out, 0o600); err != nil {
   218→		return fmt.Errorf("write repo-local droid settings %s: %w", repoSettingsPath, err)
   219→	}
   220→	return nil
   221→}
