   223→func loadJSONMap(path, description string) (map[string]json.RawMessage, error) {
   224→	data, err := os.ReadFile(path)
   225→	if err != nil {
   226→		return nil, fmt.Errorf("read %s at %s: %w", description, path, err)
   227→	}
   228→
   229→	var parsed map[string]json.RawMessage
   230→	if err := json.Unmarshal(data, &parsed); err != nil {
   231→		return nil, fmt.Errorf("parse %s at %s: %w", description, path, err)
   232→	}
   233→	if parsed == nil {
   234→		parsed = make(map[string]json.RawMessage)
   235→	}
   236→	return parsed, nil
   237→}
