   239→func ensureGitInfoExcludeContains(repoDir, entry string) error {
   240→	excludePath := filepath.Join(repoDir, ".git", "info", "exclude")
   241→
   242→	data, err := os.ReadFile(excludePath)
   243→	if err != nil && !errors.Is(err, os.ErrNotExist) {
   244→		return fmt.Errorf("read %s: %w", excludePath, err)
   245→	}
   246→
   247→	normalized := strings.ReplaceAll(string(data), "\r\n", "\n")
   248→	for _, line := range strings.Split(normalized, "\n") {
   249→		if strings.TrimSpace(line) == entry {
   250→			return nil
   251→		}
   252→	}
   253→
   254→	var b strings.Builder
   255→	if len(data) > 0 {
   256→		b.Write(data)
   257→		if data[len(data)-1] != '\n' {
   258→			b.WriteByte('\n')
   259→		}
   260→	}
   261→	b.WriteString(entry)
   262→	b.WriteByte('\n')
   263→
   264→	if err := os.MkdirAll(filepath.Dir(excludePath), 0o755); err != nil {
   265→		return fmt.Errorf("create %s: %w", filepath.Dir(excludePath), err)
   266→	}
   267→	if err := os.WriteFile(excludePath, []byte(b.String()), 0o644); err != nil {
   268→		return fmt.Errorf("write %s: %w", excludePath, err)
   269→	}
   270→	return nil
   271→}
