   523→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
   524→// checkpoint branch. It parses the two-level directory structure
   525→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
   526→func CheckpointIDs(t *testing.T, dir string) []string {
   527→	t.Helper()
   528→	out := gitOutputSafe(dir, "ls-tree", "-r", "--name-only", "entire/checkpoints/v1")
   529→	if out == "" {
   530→		return nil
   531→	}
   532→	seen := map[string]bool{}
   533→	var ids []string
   534→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
   535→		// Match {prefix}/{suffix}/metadata.json (top-level, not session-level)
   536→		parts := strings.Split(line, "/")
   537→		if len(parts) == 3 && parts[2] == "metadata.json" {
   538→			id := parts[0] + parts[1]
   539→			if !seen[id] {
   540→				seen[id] = true
   541→				ids = append(ids, id)
   542→			}
   543→		}
   544→	}
   545→	return ids
   546→}
