   885→// cleanupShadowBranchIfUnused deletes a shadow branch if no other active sessions reference it.
   886→func (s *ManualCommitStrategy) cleanupShadowBranchIfUnused(ctx context.Context, _ *git.Repository, shadowBranchName, excludeSessionID string) error {
   887→	// List all session states to check if any other session uses this shadow branch
   888→	allStates, err := s.listAllSessionStates(ctx)
   889→	if err != nil {
   890→		return fmt.Errorf("failed to list session states: %w", err)
   891→	}
   892→
   893→	for _, state := range allStates {
   894→		if state.SessionID == excludeSessionID {
   895→			continue
   896→		}
   897→		otherShadow := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
   898→		if otherShadow == shadowBranchName && state.StepCount > 0 {
   899→			// Another session still needs this shadow branch
   900→			return nil
   901→		}
   902→	}
   903→
   904→	// No other sessions need it, delete the shadow branch via CLI
   905→	// (go-git v5's RemoveReference doesn't persist with packed refs/worktrees)
   906→	if err := DeleteBranchCLI(ctx, shadowBranchName); err != nil {
   907→		// Branch already gone is not an error
   908→		if errors.Is(err, ErrBranchNotFound) {
   909→			return nil
   910→		}
   911→		return fmt.Errorf("failed to remove shadow branch: %w", err)
   912→	}
   913→	return nil
   914→}
