   810→func createBlobFromFile(repo *git.Repository, filePath string) (plumbing.Hash, filemode.FileMode, error) {
   811→	info, err := os.Stat(filePath)
   812→	if err != nil {
   813→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
   814→	}
   815→
   816→	// Determine file mode
   817→	mode := filemode.Regular
   818→	if info.Mode()&0o111 != 0 {
   819→		mode = filemode.Executable
   820→	}
   821→	if info.Mode()&os.ModeSymlink != 0 {
   822→		mode = filemode.Symlink
   823→	}
   824→
   825→	// Read file contents
   826→	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the repository
   827→	if err != nil {
   828→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
   829→	}
   830→
   831→	// Create blob object
   832→	obj := repo.Storer.NewEncodedObject()
   833→	obj.SetType(plumbing.BlobObject)
   834→	obj.SetSize(int64(len(content)))
   835→
   836→	writer, err := obj.Writer()
   837→	if err != nil {
   838→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to get object writer: %w", err)
   839→	}
   840→
   841→	_, err = writer.Write(content)
   842→	if err != nil {
   843→		_ = writer.Close()
   844→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to write blob content: %w", err)
   845→	}
   846→	if err := writer.Close(); err != nil {
   847→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to close blob writer: %w", err)
   848→	}
