// TestWorkingTreeMatchesCommit_CRLF verifies that a file committed with LF line
// endings but present on disk with CRLF (Windows autocrlf) is correctly identified
// as matching the committed blob.
func TestWorkingTreeMatchesCommit_CRLF(t *testing.T) {
	t.Parallel()

	tmpDir := t.TempDir()

	repo, err := git.PlainInit(tmpDir, false)
	require.NoError(t, err)

	// Write LF content and commit it.
	filePath := filepath.Join(tmpDir, "file.md")
	require.NoError(t, os.WriteFile(filePath, []byte("hello\nworld\n"), 0o644))

	wt, err := repo.Worktree()
	require.NoError(t, err)
	_, err = wt.Add("file.md")
	require.NoError(t, err)
	commitHash, err := wt.Commit("init", &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "t@t.com"},
	})
	require.NoError(t, err)

	// Get the blob hash for file.md from the commit.
	commitObj, err := repo.CommitObject(commitHash)
	require.NoError(t, err)
	tree, err := commitObj.Tree()
	require.NoError(t, err)
	f, err := tree.File("file.md")
	require.NoError(t, err)
	blobHash := f.Hash

	// Simulate Windows autocrlf: overwrite disk file with CRLF.
	require.NoError(t, os.WriteFile(filePath, []byte("hello\r\nworld\r\n"), 0o644))

	assert.True(t, workingTreeMatchesCommit(tmpDir, "file.md", blobHash),
		"CRLF on disk should match the LF blob committed in git")
}

// TestWorkingTreeMatchesCommit_CRLF_BinaryUntouched verifies that binary files
// (containing null bytes) are not CRLF-normalized during hash comparison.
func TestWorkingTreeMatchesCommit_CRLF_BinaryUntouched(t *testing.T) {
	t.Parallel()

	tmpDir := t.TempDir()

	repo, err := git.PlainInit(tmpDir, false)
	require.NoError(t, err)

	// Binary content with a null byte — must not be CRLF-normalized.
	binaryContent := []byte("data\r\nmore\x00bytes\r\n")
	filePath := filepath.Join(tmpDir, "binary.bin")
	require.NoError(t, os.WriteFile(filePath, binaryContent, 0o644))

	wt, err := repo.Worktree()
	require.NoError(t, err)
	_, err = wt.Add("binary.bin")
	require.NoError(t, err)
	commitHash, err := wt.Commit("init", &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "t@t.com"},
	})
	require.NoError(t, err)

	commitObj, err := repo.CommitObject(commitHash)
	require.NoError(t, err)
	tree, err := commitObj.Tree()
	require.NoError(t, err)
	f, err := tree.File("binary.bin")
	require.NoError(t, err)
